# Сводный словарь (ключи — русские названия в нижнем регистре)
# -----------------------------------------------------------------------------
HOROSCOPES_BY_SIGN: Dict[str, List[str]] = {
    "овен": HOROSCOPES_OVEN,
    "телец": HOROSCOPES_TELEC,
    "близнецы": HOROSCOPES_BLIZNECY,
    "рак": HOROSCOPES_RAK,
    "лев": HOROSCOPES_LEV,
    "дева": HOROSCOPES_DEVA,
    "весы": HOROSCOPES_VESY,
    "скорпион": HOROSCOPES_SKORPION,
    "стрелец": HOROSCOPES_STRELEC,
    "козерог": HOROSCOPES_KOZEROG,
    "водолей": HOROSCOPES_VODOLEJ,
    "рыбы": HOROSCOPES_RYBY,
}

def get_local_horoscope(sign_ru: str, for_date: datetime = None) -> str:
    """
    Возвращает локальный гороскоп для указанного знака на дату.

    Args:
        sign_ru: знак на русском (нижний регистр)
        for_date: дата, для которой нужен гороскоп (по умолчанию текущая)

    Returns:
        Текст гороскопа.
        Если знак не найден или данных нет, возвращает общую фразу.
    """
    if for_date is None:
        for_date = datetime.now()

    sign_key = sign_ru.lower()
    horoscopes = HOROSCOPES_BY_SIGN.get(sign_key)

    if not horoscopes:
        return "Сегодня звёзды молчат, но удача на вашей стороне."

    # Детерминированный выбор на основе дня года (1..366)
    day_of_year = for_date.timetuple().tm_yday
    index = (day_of_year - 1) % len(horoscopes)  # 0..27
    return horoscopes[index]